{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec3 col = normalize((texture(iChannel0, uv).rgb)*vec3(1., 1., 1.));
    // Output to screen
    fragColor = vec4(col,1.0);
}

#define t iTime
bool keyDown(int ascii) {
    return texelFetch(iChannel1,ivec2(ascii,0),0).x > 0.;
}

vec3 processPoint(vec3 point, float deltaTime) {
    float speed = .01;
    float ti = float(iFrame)/60.;
    float t = 10.;
    float p = 50.;
    float b = 4./3.;
    float x = point.x;
    float y = point.y;
    float z = point.z;

    vec3 delta;
    delta.x = t * (y - x);
    delta.y = x * (p - z) - y;
    delta.z = x*y - b*z;
    deltaTime = 1./60.;
    return mod(point + delta*deltaTime*speed + 80., 160.) + 80.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    vec3 r = texture(iChannel0, uv).rgb;
    vec3 w = processPoint(r, iTimeDelta);
    // Reset
    if (iFrame == 0 || r == vec3(0.) || keyDown(32)) {
        w = uv.xyx;
        // Run through 2000 iterations
        for (int i = 0; i < 2000; i++) {
            w = processPoint(w, iTimeDelta);
        }
    }

    // Output to screen
    fragColor = vec4(w,1.0);
}
